"""system_top.py — the Verilog top of a memory-mapped **system**, generated by walking its pysim graph.

``plans/xsi_system_top.md`` Stage 3.  A single composite kernel's top is :func:`composite_gen.render_top`;
a *system* -- several csynth'd kernels, their memory-mapped adaptors, AMD's crossbar and an on-chip
memory, reached by a host -- had its top restated by hand in each example (``render_top`` in
``markov_xsi.py`` / ``mm_fir_xsi.py``).  The pysim system already holds every fact that top needs, so
this module derives it:

====================================  ===============================================================
graph element                         emitted
====================================  ===============================================================
a csynth'd kernel inside the cut      an instance of its module, pins from its ``TopSpec`` (the same
                                      spec csynth was built from -- never a regex over the ``.v``)
a crossbar master inside the cut      an SI slot on internal wires (a kernel's ``m_axi`` bundle)
a crossbar master outside the cut     an AXI4 *slave* port group of the top, ``s<k>_axi`` -- the
                                      host's bus master faces it (``AxiMmMaster``)
a crossbar slave                      an MI slot: a view (``render_view_slot``), an adaptor
                                      (``render_adaptor_slot``), or an on-chip memory (a BRAM window)
a ``StreamIF`` between two of them    stream nets; a depth above the default on a link between two
                                      *kernels* becomes an ``mm_sync_fifo`` (a view's link IS its FIFO)
a routed credit stream                its two bus writers (``mm_writer_gen``), ``target`` from the
                                      address map
an interrupt line leaving the cut     a top output ``irq_<view>`` -- an ``IrqPin`` answers it
unused pins                           the tie-off rules, once, here (below)
====================================  ===============================================================

**The cut is a set.**  ``inside`` names the modules synthesized into the top -- the kernels and any
on-chip memory.  A kernel's memory-mapped views and adaptor come with it (they are its device), and a
routed credit stream's writers come with the link.  Everything else on the graph -- the host -- is a
BFM beside the top, and every endpoint bound to it becomes a top port.

**The tie-off rules**, stated once:

* a kernel's ``s_axi_control`` inputs are tied low -- its ``m_axi`` base register stays 0, so a bus
  address is the address;
* an ``m_axi`` pin the crossbar's SI lacks is tied low (an input) or left open (an output); the
  kernel's AWID/ARID are left open and the SI's driven 0, and BID/RID take the SI's bit 0 -- a
  Vitis master's IDs are one bit, the crossbar's are ``id_width``;
* a stream input with no driver: ``TLAST`` low, ``TKEEP``/``TSTRB`` all ones (every byte valid);
* an MI slot the crossbar config pads in (``AxiXbarConfig.from_crossbar``) answers nothing: every
  slave-driven signal held low;
* a memory's kernel port with no kernel on it is held idle.

Stream nets are the bus width wide; a narrower kernel port takes the low bits.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

from waveflow.build.axi_xbar import (
    AxiXbarConfig,
    axi_port_decls,
    axi_signals,
    axi_wire_decls,
    render_xbar_instance,
)
from waveflow.build.composite_gen import ExtPort, _CONTROL_UNDRIVEN
from waveflow.build.hwcodegen import LoweringError
from waveflow.build.mm_adaptor_gen import (
    BramView,
    CreditInView,
    QueueView,
    RegBankView,
    mi_wire_signals,
    render_adaptor_slot,
    render_view_slot,
)
from waveflow.hw.interface import DEFAULT_STREAM_DEPTH

if TYPE_CHECKING:
    from waveflow.build.composite_gen import TbSpec

#: A Vitis ``m_axi`` bundle's pins, ``(signal, is_input)``: both channels, always, whatever the
#: pointer's direction -- Vitis 2025.1 emits the full set (checked against the csynth'd modules by
#: ``tests/build/test_system_top.py`` whenever their RTL is present).
VITIS_MAXI_PINS: tuple[tuple[str, bool], ...] = tuple(
    (s, s in ("AWREADY", "WREADY", "ARREADY", "RVALID", "RDATA", "RLAST", "RID", "RUSER", "RRESP",
              "BVALID", "BRESP", "BID", "BUSER"))
    for s in ("AWVALID", "AWREADY", "AWADDR", "AWID", "AWLEN", "AWSIZE", "AWBURST", "AWLOCK",
              "AWCACHE", "AWPROT", "AWQOS", "AWREGION", "AWUSER", "WVALID", "WREADY", "WDATA",
              "WSTRB", "WLAST", "WID", "WUSER", "ARVALID", "ARREADY", "ARADDR", "ARID", "ARLEN",
              "ARSIZE", "ARBURST", "ARLOCK", "ARCACHE", "ARPROT", "ARQOS", "ARREGION", "ARUSER",
              "RVALID", "RREADY", "RDATA", "RLAST", "RID", "RUSER", "RRESP", "BVALID", "BREADY",
              "BRESP", "BID", "BUSER"))

#: The ``s_axi_control`` slave Vitis adds beside an ``offset=slave`` ``m_axi`` port: its inputs are
#: the testbench's :data:`~waveflow.build.composite_gen._CONTROL_UNDRIVEN`; these are its outputs.
_CONTROL_OUTPUTS = ("AWREADY", "WREADY", "ARREADY", "RVALID", "RDATA", "RRESP", "BVALID", "BRESP")

_AXIS_SIDE = ("TDATA", "TVALID", "TLAST", "TKEEP", "TSTRB")     # producer-driven; TREADY goes back


@dataclass(frozen=True)
class KernelRtl:
    """One csynth'd module inside the top: what it is called and what pins it has.

    ``ports`` are its boundary :class:`~waveflow.build.composite_gen.ExtPort`\\ s -- the same spec its
    csynth top was rendered from; ``scalars`` its ``ap_none`` inputs as ``(name, width, value)``
    (a routed writer's ``target``); ``endpoints`` the system instance's endpoint per port name, which
    is how a pin finds its net."""

    module: str
    inst: str
    ports: tuple[ExtPort, ...]
    scalars: tuple[tuple[str, int, int], ...] = ()
    endpoints: tuple[tuple[str, object], ...] = ()


def kernel_pins(k: KernelRtl) -> list[tuple[str, str]]:
    """``(direction, name)`` of every pin of *k*'s module, derived from its spec.

    The rules are Vitis's, for the port kinds a free-running top has: an AXIS port has
    TDATA/TVALID/TREADY, plus TLAST/TKEEP/TSTRB when it carries the side channels (``axi4s``); an
    ``m_axi`` port has :data:`VITIS_MAXI_PINS` under ``m_axi_<bundle>_`` and brings the
    ``s_axi_control`` slave with it; a scalar is one input."""
    pins = [("input", "ap_clk"), ("input", "ap_rst_n")]
    maxi = False
    for p in k.ports:
        if p.kind in ("axis_in", "axis_out"):
            fwd = "input" if p.kind == "axis_in" else "output"
            back = "output" if fwd == "input" else "input"
            sigs = ["TDATA", "TVALID"] + (["TLAST", "TKEEP", "TSTRB"] if p.axi4s else [])
            pins += [(fwd, f"{p.name}_{s}") for s in sigs] + [(back, f"{p.name}_TREADY")]
        elif p.kind in ("maxi_read", "maxi_write"):
            maxi = True
            pins += [("input" if i else "output", f"{p.xsi_prefix}_{s}") for s, i in VITIS_MAXI_PINS]
        else:
            raise LoweringError(f"{k.module}: port {p.name!r} is kind {p.kind!r}, which a system top "
                                f"has no rule to wire")
    if maxi:
        pins += [("input", n) for n in _CONTROL_UNDRIVEN]
        pins += [("output", f"s_axi_control_{s}") for s in _CONTROL_OUTPUTS]
    pins += [("input", n) for n, _w, _v in k.scalars]
    return pins


@dataclass(frozen=True)
class StreamNet:
    """One stream link inside the top.  ``fifo_depth`` > 0 puts an ``mm_sync_fifo`` on it: the
    producer drives ``<name>``, the consumer reads ``<name>_q``."""

    name: str
    fifo_depth: int = 0
    producer_tlast: bool = True        # does whatever drives the (producer-side) net drive TLAST?
    consumer_tlast: bool = True        # does the consumer read TLAST?
    producer_keep: bool = False        # ...and TKEEP / TSTRB (only a kernel with side channels)?
    consumer_keep: bool = False

    @property
    def consumer_net(self) -> str:
        return f"{self.name}_q" if self.fifo_depth else self.name


@dataclass(frozen=True)
class MiSlot:
    """One crossbar MI slot: a view, an adaptor's views, an on-chip memory, or a stub (``views=()``)."""

    kind: str                          # "view" | "adaptor" | "memory" | "stub"
    name: str = ""
    views: tuple = ()


@dataclass(frozen=True)
class SystemTopSpec:
    """A system top, derived (:func:`system_top_spec`) and answerable before it is rendered."""

    top: str
    xbar: AxiXbarConfig
    #: Per crossbar SI slot: ``(prefix, outside)`` -- ``s<k>_axi`` a top port, ``si<k>_axi`` a wire.
    si: tuple[tuple[str, bool], ...]
    mi: tuple[MiSlot, ...]
    nets: tuple[StreamNet, ...]
    kernels: tuple[KernelRtl, ...]
    #: ``(top output, view name)`` -- the interrupt lines that leave the cut.
    irqs: tuple[tuple[str, str], ...] = ()
    #: Kernel instance -> its m_axi port -> the SI prefix it drives.
    maxi_si: tuple[tuple[str, str, str], ...] = ()
    #: Kernel instance -> its AXIS port -> ``(net name, side)``: side "p" (it drives) or "c".
    axis_nets: tuple[tuple[str, str, str], ...] = ()
    #: An on-chip memory's unused kernel ports, by BramView.kport.
    idle_memory_ports: tuple[str, ...] = ()
    #: ``id(endpoint) -> net`` for every stream endpoint on a net inside the top, and
    #: ``id(bus master) -> its SI prefix`` -- what lets a :class:`Probe` name a pysim object instead
    #: of a net.  Identities of the graph the spec was walked from: resolve probes against that graph.
    ep_nets: tuple[tuple[int, str], ...] = ()
    ep_si: tuple[tuple[int, str], ...] = ()

    def probe_expr(self, probe: "Probe | str") -> str:
        """The one-bit Verilog expression for *probe* over this top's nets (a string passes through)."""
        if isinstance(probe, str):
            return probe
        return probe.expr(dict(self.ep_nets), dict(self.ep_si))

    @property
    def host_axi(self) -> tuple[str, ...]:
        """The AXI4 slave port groups of the top -- one per bus master outside the cut."""
        return tuple(p for p, outside in self.si if outside)

    @property
    def modules(self) -> tuple[str, ...]:
        """The csynth'd modules the top instantiates, each once -- whose RTL a workspace compiles."""
        return tuple(dict.fromkeys(k.module for k in self.kernels))


def default_id_width(n_si: int) -> int:
    """Enough AXI ID bits for the crossbar to route a response back to each of *n_si* masters."""
    return max(1, (int(n_si) - 1).bit_length())


def _rtl_of(mod, dw: int) -> KernelRtl:
    """*mod*'s module name and ports.  A kernel's come from ``composite_top_spec`` on a fresh
    instance -- exactly as its csynth top was built (``<example>_build.gen_top``) -- and a routed
    writer's from :func:`~waveflow.build.mm_writer_gen.writer_rtl`."""
    from waveflow.build.composite_gen import _unpack_boundary, composite_top_spec
    from waveflow.hw.mm_credit import MmStreamWriter
    from waveflow.simulation.simulation import Simulation

    if isinstance(mod, MmStreamWriter):
        from waveflow.build.mm_writer_gen import writer_rtl
        module, ports, scalars = writer_rtl(mod)
        eps = (("s_in", mod.s_in), ("m_mem", mod.m_mem))
        return KernelRtl(module, f"u_{mod.name}", ports, scalars, eps)
    name = getattr(type(mod), "cpp_kernel_name", None)
    if not name:
        raise LoweringError(f"{type(mod).__name__} '{mod.name}' is inside the cut but names no "
                            f"csynth'd module (cpp_kernel_name)")
    spec = composite_top_spec(type(mod)(name=name, sim=Simulation()), width=dw)
    eps = tuple(_unpack_boundary(e) for e in mod.boundary)
    return KernelRtl(spec.top_name, f"u_{mod.name}", tuple(spec.ports), (), eps)


def _view_of(v, net_of: dict, law_default: int):
    """The RTL view (``mm_adaptor_gen``) for pysim view module *v*, its streams on their nets."""
    from waveflow.hw.mm_bram import MemSlaveBramWindow
    from waveflow.hw.mm_credit import MemSlaveCreditIn
    from waveflow.hw.mm_queue import MemSlaveRStream, MemSlaveWStream
    from waveflow.hw.mm_regbank import MemSlaveRegBank

    law = int(getattr(v, "window", 1 << law_default)).bit_length() - 1
    if isinstance(v, MemSlaveWStream):
        return QueueView(v.name, "in", axis=net_of[id(v.m_out)], depth=int(v.depth), law=law)
    if isinstance(v, MemSlaveRStream):
        return QueueView(v.name, "out", axis=net_of[id(v.s_in)], depth=int(v.depth), law=law)
    if isinstance(v, MemSlaveRegBank):
        return RegBankView(v.name, ncfg=int(v.ncfg), nstat=int(v.nstat),
                           cfg_axis=net_of[id(v.m_cfg)], status_axis=net_of[id(v.s_status)],
                           law=law)
    if isinstance(v, MemSlaveCreditIn):
        return CreditInView(v.name, axis=net_of[id(v.m_out)], law=law)
    if isinstance(v, MemSlaveBramWindow):
        raise LoweringError(f"view '{v.name}': a BRAM window shared with a kernel is not wired by "
                            f"system_top yet")
    raise LoweringError(f"no RTL view for {type(v).__name__} '{v.name}'")


def _views_of_device(dev):
    return list(dev.adaptor.views) if dev.adaptor is not None else list(dev.views.values())


def system_top_spec(xbar, inside, *, top: str = "system_top", xbar_name: str | None = None,
                    id_width: int | None = None) -> SystemTopSpec:
    """Walk the pysim system around crossbar *xbar* and derive its RTL top, cut at *inside*.

    *inside* is the set of modules synthesized into the top: kernels (``FreeRunMod``\\ s with a
    csynth'd module) and on-chip memories (``MemoryMod``).  Their devices' views and adaptors, and
    the writers of any routed credit stream between them, are inside with them.
    """
    from waveflow.hw.interface import StreamIF
    from waveflow.hw.memory import MemoryMod
    from waveflow.hw.mm_credit import MmStreamWriter

    inside = list(inside)
    ids = {id(m) for m in inside}
    dw = int(xbar.bitwidth)
    n_si = int(xbar.nports_master)
    idw = default_id_width(n_si) if id_width is None else int(id_width)
    cfg = AxiXbarConfig.from_crossbar(xbar, xbar_name or f"xbar_{top}", id_width=idw)

    kernels_mods = [m for m in inside if not isinstance(m, MemoryMod)]

    # --- the kernels and writers, and the stream links between them and their views -------------
    # Discover writers: a kernel's AXIS boundary port whose peer belongs to an MmStreamWriter.
    rtl: list[KernelRtl] = []
    owner_rtl: dict[int, KernelRtl] = {}      # id(endpoint) -> the KernelRtl that pins it
    queue = list(kernels_mods)
    seen: set[int] = set()
    while queue:
        mod = queue.pop(0)
        if id(mod) in seen:
            continue
        seen.add(id(mod))
        k = _rtl_of(mod, dw)
        rtl.append(k)
        for _n, ep in k.endpoints:
            owner_rtl[id(ep)] = k
            iface = getattr(ep, "interface", None)
            if isinstance(iface, StreamIF):
                for peer in iface.endpoints.values():
                    if peer is not ep and isinstance(getattr(peer, "comp", None), MmStreamWriter):
                        queue.append(peer.comp)
    port_of: dict[int, tuple[KernelRtl, ExtPort]] = {}
    for k in rtl:
        by_name = {p.name: p for p in k.ports}
        for n, ep in k.endpoints:
            if n not in by_name:
                raise LoweringError(f"{k.module}: boundary endpoint {n!r} has no port in its spec")
            port_of[id(ep)] = (k, by_name[n])

    nets: list[StreamNet] = []
    net_of: dict[int, str] = {}               # id(endpoint) -> the net it is on
    axis_nets: list[tuple[str, str, str]] = []
    done_ifaces: set[int] = set()
    for k in rtl:
        for n, ep in k.endpoints:
            p = port_of[id(ep)][1]
            if p.kind not in ("axis_in", "axis_out"):
                continue
            iface = ep.interface
            if not isinstance(iface, StreamIF):
                raise LoweringError(f"{k.module}.{n}: an AXIS port must be on a StreamIF inside the "
                                    f"top (it is on {type(iface).__name__})")
            if id(iface) in done_ifaces:
                continue
            done_ifaces.add(id(iface))
            m_ep, s_ep = iface.endpoints["master"], iface.endpoints["slave"]
            prod, cons = port_of.get(id(m_ep)), port_of.get(id(s_ep))
            # A link between two kernels with a real depth is a FIFO in RTL too; a view's link IS the
            # view's FIFO, so it is a plain net.
            depth = int(iface.depth or DEFAULT_STREAM_DEPTH)
            fifo = depth if (prod and cons and depth > DEFAULT_STREAM_DEPTH) else 0
            net = StreamNet(
                iface.name, fifo_depth=fifo,
                producer_tlast=(prod[1].axi4s if prod else True),       # every leaf drives TLAST
                consumer_tlast=(cons[1].axi4s if cons else True),       # ...and reads it
                producer_keep=(prod[1].axi4s if prod else False),       # no leaf has TKEEP
                consumer_keep=(cons[1].axi4s if cons else False))
            nets.append(net)
            net_of[id(m_ep)] = net.name
            net_of[id(s_ep)] = net.consumer_net
            if prod:
                axis_nets.append((prod[0].inst, prod[1].name, net.name))
            if cons:
                axis_nets.append((cons[0].inst, cons[1].name, net.consumer_net))

    # --- the crossbar -------------------------------------------------------------------------------
    si: list[tuple[str, bool]] = []
    maxi_si: list[tuple[str, str, str]] = []
    ep_si: list[tuple[int, str]] = []
    for kk in range(n_si):
        ep = xbar.endpoints.get(f"master_{kk}")
        hit = port_of.get(id(ep))
        if hit is None:
            si.append((f"s{kk}_axi", True))           # a master outside the cut: the top's port
        else:
            si.append((f"si{kk}_axi", False))
            maxi_si.append((hit[0].inst, hit[1].name, f"si{kk}_axi"))
        ep_si.append((id(ep), si[-1][0]))

    mi: list[MiSlot] = []
    idle_mem: list[str] = []
    irqs: list[tuple[str, str]] = []
    for kk in range(len(cfg.mi)):
        ep = xbar.endpoints.get(f"slave_{kk}")
        if ep is None:
            mi.append(MiSlot("stub"))
            continue
        mod = ep.comp
        dev = getattr(mod, "mm_device", None)
        if isinstance(mod, MemoryMod):
            if id(mod) not in ids:
                raise LoweringError(f"memory '{mod.name}' is on the crossbar but not inside the cut; "
                                    f"an off-chip memory (a FlatMemory beside the top) is not wired "
                                    f"by system_top yet")
            nwords = int(mod.nwords_tot)
            baw = nwords.bit_length() - 1
            if nwords != 1 << baw:
                raise LoweringError(f"memory '{mod.name}': {nwords} words is not a power of two")
            law = int(ep.addr_range.size).bit_length() - 1
            kport = f"{mod.name}_b"
            mi.append(MiSlot("memory", mod.name, (BramView(mod.name, kport=kport, baw=baw, law=law),)))
            idle_mem.append(kport)
            continue
        if dev is None or id(dev.kernel) not in ids:
            raise LoweringError(f"crossbar slave_{kk} ({type(mod).__name__} '{getattr(mod, 'name', '?')}') "
                                f"is not the device of a kernel inside the cut")
        views = [mod] if dev.adaptor is None else list(dev.adaptor.views)
        rviews = tuple(_view_of(v, net_of, 12) for v in views)
        mi.append(MiSlot("adaptor" if dev.adaptor is not None else "view",
                         mod.name, rviews))
        for v in views:
            line = getattr(getattr(v, "m_irq", None), "interface", None)
            sink = line.endpoints.get("sink") if line is not None else None
            if sink is not None and id(getattr(sink, "comp", None)) not in ids:
                irqs.append((f"irq_{v.name}", v.name))

    return SystemTopSpec(top=top, xbar=cfg, si=tuple(si), mi=tuple(mi), nets=tuple(nets),
                         kernels=tuple(rtl), irqs=tuple(irqs), maxi_si=tuple(maxi_si),
                         axis_nets=tuple(axis_nets), idle_memory_ports=tuple(idle_mem),
                         ep_nets=tuple(net_of.items()), ep_si=tuple(ep_si))


# ---------------------------------------------------------------------------
# Timing probes, named by the pysim object they watch
# ---------------------------------------------------------------------------

_AXI_CHANNELS = ("AW", "W", "B", "AR", "R")


@dataclass(frozen=True)
class Probe:
    """A one-bit timing probe on a pysim endpoint -- resolved to the top's nets by the spec, so the
    user names *what* to watch (``sysm.gen.s_cmd``) and never a net.

    * a **stream endpoint** (a kernel's or a view's port inside the top): the net it is on --
      the producer's side of a FIFO'd link for the producer, the consumer's side for the consumer;
    * a **bus master** (``MMIFMaster``) on the crossbar: its SI slot, on one AXI channel
      (``"AW"``, ``"W"``, ``"B"``, ``"AR"``, ``"R"``).

    Build them with :func:`beat`, :func:`stall` and :func:`last`."""

    ep: object
    kind: str = "beat"                 # "beat" | "stall" | "last"
    channel: str | None = None         # AXI channel, for a bus master

    def expr(self, ep_nets: dict, ep_si: dict) -> str:
        name = getattr(self.ep, "name", self.ep)
        if id(self.ep) in ep_si:
            if self.channel not in _AXI_CHANNELS:
                raise LoweringError(f"probe on bus master {name!r}: name its AXI channel, one of "
                                    f"{_AXI_CHANNELS} (e.g. beat(m, 'AW'))")
            pre = f"{ep_si[id(self.ep)]}_{self.channel}"
        elif id(self.ep) in ep_nets:
            if self.channel is not None:
                raise LoweringError(f"probe on stream endpoint {name!r}: a stream has no AXI channel")
            pre = f"{ep_nets[id(self.ep)]}_T"
        else:
            raise LoweringError(f"probe on {name!r}: it is not a stream endpoint on a net inside the "
                                f"top, nor a bus master on its crossbar")
        v, r = f"{pre}VALID", f"{pre}READY"
        if self.kind == "beat":
            return f"{v} && {r}"
        if self.kind == "stall":
            return f"{v} && !{r}"
        if self.kind == "last":
            if self.channel not in (None, "W", "R"):
                raise LoweringError(f"probe on {name!r}: only a stream, W or R carries LAST")
            return f"{v} && {r} && {pre}LAST" if self.channel else f"{v} && {r} && {pre[:-1]}TLAST"
        raise LoweringError(f"probe kind must be beat, stall or last, got {self.kind!r}")


def beat(ep, channel: str | None = None) -> Probe:
    """High on every cycle a word moves: ``VALID && READY`` on *ep*'s net (or its *channel*)."""
    return Probe(ep, "beat", channel)


def stall(ep, channel: str | None = None) -> Probe:
    """High on every cycle *ep*'s producer offers a word nobody takes: ``VALID && !READY``."""
    return Probe(ep, "stall", channel)


def last(ep, channel: str | None = None) -> Probe:
    """High on the beat that ends a packet: ``VALID && READY && LAST``."""
    return Probe(ep, "last", channel)


def _stream_wires(net: str, dw: int) -> list[str]:
    return [f"  wire [{dw - 1}:0] {net}_TDATA;", f"  wire {net}_TVALID, {net}_TREADY, {net}_TLAST;",
            f"  wire [{dw // 8 - 1}:0] {net}_TKEEP, {net}_TSTRB;"]


def _fifo(net: StreamNet, dw: int) -> list[str]:
    """``mm_sync_fifo`` from ``<net>`` to ``<net>_q``, carrying TLAST beside TDATA."""
    n, q, d = net.name, net.consumer_net, int(net.fifo_depth)
    f = f"{n}_ff"
    return [
        f"  // {n}: a {d}-word FIFO between two kernels (the link's declared depth)",
        f"  wire [{dw}:0] {f}_dout; wire {f}_full, {f}_empty; wire [$clog2({d}):0] {f}_count;",
        f"  mm_sync_fifo #(.W({dw + 1}), .DEPTH({d})) u_{f} (",
        "    .clk(ap_clk), .rst_n(ap_rst_n),",
        f"    .push({n}_TVALID && !{f}_full), .din({{{n}_TLAST, {n}_TDATA}}),",
        f"    .pop({q}_TVALID && {q}_TREADY), .dout({f}_dout),",
        f"    .full({f}_full), .empty({f}_empty), .count({f}_count));",
        f"  assign {n}_TREADY = !{f}_full;",
        f"  assign {q}_TVALID = !{f}_empty;",
        f"  assign {q}_TDATA = {f}_dout[{dw - 1}:0];",
        f"  assign {q}_TLAST = {f}_dout[{dw}];",
    ]


def _instance(k: KernelRtl, spec: SystemTopSpec, dw: int, aw: int, idw: int) -> str:
    """Instantiate *k*, connecting every pin of :func:`kernel_pins` by the rules in the module doc."""
    si_of = {port: p for inst, port, p in spec.maxi_si if inst == k.inst}
    net_of = {port: n for inst, port, n in spec.axis_nets if inst == k.inst}
    ports = {p.name: p for p in k.ports}
    prefix_port = {p.xsi_prefix: p.name for p in k.ports if p.kind in ("maxi_read", "maxi_write")}
    si_sigs = {name for name, _w, _m in axi_signals(dw, aw, idw)}
    scalars = {n: (w, v) for n, w, v in k.scalars}
    conns = []
    for d, name in kernel_pins(k):
        tie = "0" if d == "input" else ""
        if name in ("ap_clk", "ap_rst_n"):
            conns.append(f".{name}({name})")
        elif name in scalars:
            w, v = scalars[name]
            conns.append(f".{name}({w}'d{int(v)})")
        elif name.startswith("s_axi_control_"):
            conns.append(f".{name}({tie})")
        elif any(name.startswith(pre + "_") for pre in prefix_port):
            pre = next(pre for pre in prefix_port if name.startswith(pre + "_"))
            sig = name[len(pre) + 1:]
            si = si_of.get(prefix_port[pre])
            if si is None:
                raise LoweringError(f"{k.inst}: m_axi port {prefix_port[pre]!r} is on no crossbar SI")
            if sig not in si_sigs:
                conns.append(f".{name}({tie})")
            elif sig in ("AWID", "ARID"):
                conns.append(f".{name}()")                    # the SI side is driven 0 instead
            elif sig in ("BID", "RID"):
                conns.append(f".{name}({si}_{sig}[0])")
            else:
                conns.append(f".{name}({si}_{sig})")
        else:
            port, _, sig = name.rpartition("_")
            if port not in ports or port not in net_of:
                raise LoweringError(f"{k.inst}: pin {name!r} belongs to no wired stream port")
            conns.append(f".{name}({net_of[port]}_{sig})")
    return f"  {k.module} {k.inst} (\n    " + ",\n    ".join(conns) + "\n  );"


def render_system_top(spec: SystemTopSpec, probes: dict | None = None) -> str:
    """Emit the Verilog top *spec* describes.  *probes* -- ``{name: Probe}`` (:func:`beat`,
    :func:`stall`, :func:`last` on a pysim endpoint) or ``{name: one-bit expression}`` over the top's
    nets -- become outputs ``probe_<name>`` (timing probes a testbench samples every cycle)."""
    cfg = spec.xbar
    dw, aw, idw = cfg.data_width, cfg.addr_width, cfg.id_width
    probes = {n: spec.probe_expr(e) for n, e in (probes or {}).items()}
    ports = ["input wire ap_clk", "input wire ap_rst_n"]
    for p in spec.host_axi:
        ports += axi_port_decls(p, axi_signals(dw, aw, idw), facing="slave")
    ports += [f"output wire {o}" for o, _v in spec.irqs]
    ports += [f"output wire probe_{n}" for n in probes]

    body: list[str] = []
    for p, outside in spec.si:
        if not outside:
            body += ["  " + d for d in axi_wire_decls(p, axi_signals(dw, aw, idw))]
            body += [f"  assign {p}_AWID = 0;", f"  assign {p}_ARID = 0;"]
    mi = [f"mi{k}_axi" for k in range(len(spec.mi))]
    for p in mi:
        body += ["  " + d for d in axi_wire_decls(p, mi_wire_signals(dw, aw, idw))]
    for net in spec.nets:
        body += _stream_wires(net.name, dw)
        if net.fifo_depth:
            body += _stream_wires(net.consumer_net, dw)
    for net in spec.nets:
        if net.fifo_depth:
            body += _fifo(net, dw)
            if not net.producer_tlast:
                body.append(f"  assign {net.name}_TLAST = 1'b0;")
            if net.consumer_keep:
                body += [f"  assign {net.consumer_net}_TKEEP = {{{dw // 8}{{1'b1}}}};",
                         f"  assign {net.consumer_net}_TSTRB = {{{dw // 8}{{1'b1}}}};"]
            continue
        if net.consumer_tlast and not net.producer_tlast:
            body.append(f"  assign {net.name}_TLAST = 1'b0;")
        if net.consumer_keep and not net.producer_keep:
            body += [f"  assign {net.name}_TKEEP = {{{dw // 8}{{1'b1}}}};",
                     f"  assign {net.name}_TSTRB = {{{dw // 8}{{1'b1}}}};"]
    body.append(render_xbar_instance(cfg, "u_xbar", [p for p, _o in spec.si], mi))
    for slot, p in zip(spec.mi, mi):
        if slot.kind == "stub":
            body.append(f"  // MI slot {p}: padded in by the crossbar config, never addressed")
            body += [f"  assign {p}_{name} = 0;" for name, _w, m2s in mi_wire_signals(dw, aw, idw)
                     if not m2s]
        elif slot.kind == "adaptor":
            body.append(render_adaptor_slot(slot.name, slot.views, p, dw, aw, idw))
        else:
            if slot.kind == "memory":
                k = slot.views[0].kport
                body += [f"  wire [31:0] {k}_addr = 0; wire {k}_en = 1'b0; wire [1:0] {k}_we = 2'b0;",
                         f"  wire [{dw - 1}:0] {k}_din = 0; wire [{dw - 1}:0] {k}_dout;"]
            body.append(render_view_slot(slot.views[0], p, dw, aw, idw))
    body += [f"  assign {o} = {v}_irq;" for o, v in spec.irqs]
    body += [f"  assign probe_{n} = {e};" for n, e in probes.items()]
    for k in spec.kernels:
        body.append(_instance(k, spec, dw, aw, idw))
    return (f"// {spec.top}.v -- GENERATED by waveflow (build/system_top.py) from the pysim system.\n"
            f"`timescale 1ns/1ps\nmodule {spec.top} (\n  " + ",\n  ".join(ports) + "\n);\n"
            + "\n".join(body) + "\nendmodule\n")


# ---------------------------------------------------------------------------
# The harness: the models beside the top (plans/xsi_system_top.md S4)
# ---------------------------------------------------------------------------

def field_position(schema, name: str, word_bw: int) -> tuple[int, int, int]:
    """``(word, bit, width)`` of field *name* in *schema*'s *word_bw*-bit serialization -- read off
    the schema's own serializer and the field's type, so a host model that must pick one field out of
    a message (which job a response answers) is handed its position rather than restating it."""
    import numpy as np

    words = np.asarray(schema(**{name: 1}).serialize(word_bw=int(word_bw)), dtype=np.uint64)
    width = int(schema.elements[name]["schema"].bitwidth)
    for i, w in enumerate(words):
        if int(w):
            return i, int(w).bit_length() - 1, width
    raise LoweringError(f"{schema.__name__}.{name}: setting it to 1 set no bit")


def system_tb_spec(spec: SystemTopSpec, xbar, participants, probes=()) -> "TbSpec":
    """The XSI harness for a system top: one model per participant's ``bfm_model()``, each port bound
    to the top port it faces.

    The resolution is :func:`~waveflow.build.composite_gen.tb_top_spec`'s, with the system top as the
    DUT: a participant's bus master faces the crossbar SI it is bound to (``s<k>_axi``), and an
    ``IrqIFSink`` faces the interrupt output of the view its line comes from (``irq_<view>``).  Each
    participant is first checked with ``resolve_bfm_model`` -- the ``xsi_bfm_model`` verdict.  The
    first participant's first model is the one whose ``done()`` ends the run (:attr:`TbSpec.stop_on`).

    *probes* names the top's ``probe_<name>`` outputs to sample (a ``ProbePin`` each, printed after the run).
    """
    from waveflow.build.composite_gen import (
        BfmInst,
        TbSpec,
        _bfm_port_attrs,
        _bfm_port_endpoint,
        _render_dyn_value,
        bfm_model_header,
        bfm_models,
        resolve_bfm_model,
    )
    from waveflow.build.sw_host_gen import endpoints_header, render_host_endpoints_h
    from waveflow.hw.hw_module import discover_dyn_params
    from waveflow.hw.irq import IrqIFSink

    ns = f"{spec.top}_ports"
    irq_port = {view: port for port, view in spec.irqs}
    master_port = {id(xbar.endpoints.get(f"master_{k}")): p
                   for k, (p, outside) in enumerate(spec.si) if outside}
    models: list = []
    local: list[str] = []
    for part in participants:
        resolve_bfm_model(part)
        dyn = tuple((f, _render_dyn_value(v)) for f, v in sorted(discover_dyn_params(part).items()))
        declared = bfm_models(part)
        for i, bm in enumerate(declared):
            binds: list[str] = []
            first = ""
            for attr in _bfm_port_attrs(bm):
                ep = _bfm_port_endpoint(part, attr)
                port = master_port.get(id(ep))
                if port is None and isinstance(ep, IrqIFSink) and ep.interface is not None:
                    src = ep.interface.endpoints.get("source")
                    port = irq_port.get(getattr(getattr(src, "comp", None), "name", None))
                if port is None:
                    raise LoweringError(
                        f"{type(part).__name__}.{attr} faces no port of {spec.top}: it is not bound "
                        f"to a crossbar master outside the cut, nor to an interrupt line leaving it.")
                binds += ["sim.dut()", f"{ns}::{port}"]
                first = first or port
            name = part.name if len(declared) == 1 else f"{part.name}_{i}"
            hdr = bfm_model_header(part, bm)
            if hdr is not None and str(hdr) not in local:
                local.append(str(hdr))
            models.append(BfmInst(bm.cls, name, first, bm.extra_args, dyn if i == 0 else (),
                                  binds=tuple(binds)))
    for n in probes:
        models.append(BfmInst("ProbePin", f"pr_{n}", f"probe_{n}", (f'"{n}"',),
                              binds=("sim.dut()", f'"probe_{n}"')))
    stop = models[0].name if participants else None
    from waveflow.sw import SwHost
    extra = tuple((endpoints_header(p), render_host_endpoints_h(p))
                  for p in participants if isinstance(p, SwHost))
    return TbSpec(top_name=spec.top, models=tuple(models), local_headers=tuple(local), stop_on=stop,
                  extra_files=extra)


def render_system_ports_h(spec: SystemTopSpec) -> str:
    """``<top>_ports.h`` for a system top: what :func:`~waveflow.build.composite_gen.render_ports_h`
    gives a kernel's harness -- the elaborated module, its DLL, one constant per port a model binds,
    and ``ZERO_PORTS``, which is empty: every input of a system top belongs to a host model."""
    ns = f"{spec.top}_ports"
    guard = f"WAVEFLOW_GEN_{ns.upper()}_H"
    lines = [
        f"#ifndef {guard}", f"#define {guard}",
        f"// {ns}.h -- GENERATED by waveflow (build/system_top.py::render_system_ports_h) from the",
        f"// same SystemTopSpec that rendered {spec.top}.v.  DO NOT EDIT: regenerate instead.",
        "", f"namespace {ns} {{", "",
        f'static const char* const TOP        = "{spec.top}";',
        "#ifdef _WIN32",
        f'static const char* const DESIGN_DLL = "xsim.dir/{spec.top}/xsimk.dll";',
        "#else",
        f'static const char* const DESIGN_DLL = "xsim.dir/{spec.top}/xsimk.so";',
        "#endif", "",
    ]
    lines += [f'static const char* const {p} = "{p}";   // AXI4 slave: a bus master outside the cut'
              for p in spec.host_axi]
    lines += [f'static const char* const {o} = "{o}";   // interrupt output of view {v}'
              for o, v in spec.irqs]
    lines += ["", "// Every input of the top is driven by a model: nothing left to pin.",
              "static const char* const ZERO_PORTS[] = { nullptr };",
              "static const int ZERO_PORTS_N = 0;", "", f"}}  // namespace {ns}", "",
              f"#endif  // {guard}"]
    return "\n".join(lines) + "\n"


def render_system_tb(spec: SystemTopSpec, tb, n_max: int = 1_000_000) -> tuple[str, dict[str, str]]:
    """The whole testbench for a system top: ``(main .cpp, {file name: text})`` -- the ports header,
    the generated harness and every example-local model header it includes.  The main constructs the
    harness, runs it until the host is done (at most *n_max* cycles), and exits 0 only if it is."""
    from pathlib import Path

    from waveflow.build.composite_gen import render_tb_harness

    files = {f"{spec.top}_ports.h": render_system_ports_h(spec),
             f"{spec.top}_tb_harness.h": render_tb_harness(tb)}
    for h in tb.local_headers:
        files[Path(h).name] = Path(h).read_text(encoding="utf-8")
    files.update(dict(tb.extra_files))
    main = "\n".join([
        f"// {spec.top}_tb.cpp -- GENERATED by waveflow (build/system_top.py::render_system_tb).",
        "// Construct the harness, run until the host is done, close.  The models report.",
        f'#include "{spec.top}_tb_harness.h"',
        "",
        "int main() {",
        f'    {spec.top}_tb::Harness h("{spec.top}.wdb");',
        f"    h.run_until({int(n_max)});",
        "    h.close();",
        f"    return h.{tb.stop_on}.done() ? 0 : 1;",
        "}",
    ]) + "\n"
    return main, files


